.card{position:relative;min-height:100vh;padding:22px;border:1px solid #ffffff13;border-radius:26px;background:radial-gradient(ellipse at 100% 0,#30405b65,transparent 60%),linear-gradient(145deg,#1b2230,#101621);box-shadow:inset 0 1px #ffffff0a;transform:perspective(900px) rotateX(var(--rx,0deg)) rotateY(var(--ry,0deg));transition:transform .2s ease;overflow:hidden}
h1,h2,p{margin:0}h1{font-size:26px;letter-spacing:-.045em;font-weight:650;line-height:1.12}h2{font-size:17px;letter-spacing:-.02em}
