header,.row{display:flex;align-items:center;justify-content:space-between;gap:10px}.row{margin-top:14px;flex-wrap:wrap}
button,input{font:inherit;border-radius:14px;min-height:44px;padding:10px 14px}button{border:1px solid #ffffff10;background:var(--accent);color:#221a17;font-weight:650;cursor:pointer;transition:transform .15s,background .15s}button:active{transform:scale(.96)}button.secondary{background:#ffffff0a;color:var(--ink)}button:disabled{opacity:.45;cursor:default}input{min-width:0;flex:1;width:100%;background:#090f19;color:var(--ink);border:1px solid #ffffff20}
.status,.muted,small{color:var(--muted);font-size:11px;overflow-wrap:anywhere}.status{margin-top:12px;line-height:1.5}.metrics{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:16px 0}.metrics strong{display:block;font-size:25px;letter-spacing:-.04em}.metrics span{color:var(--muted);font-size:11px}
ul{list-style:none;margin:16px 0;padding:0}li{padding:12px 0;border-bottom:1px solid #ffffff0b}li button{width:100%;text-align:left;background:#ffffff08;color:var(--ink)}a{color:var(--cyan)}summary{padding:12px 0;cursor:pointer;color:var(--muted);font-size:11px}button:focus-visible,input:focus-visible,summary:focus-visible{outline:2px solid var(--cyan);outline-offset:3px}[hidden]{display:none!important}
